/*
The multi-faith taxonomy (recursive religion_taxa + closure) with a catalog-driven level marker,
the religion-type classifications, the per-faith catalogs, and the per-unit organization attributes.
Reads gate on `religion.read`; taxonomy/catalog writes on `religion.catalog.manage` (instance);
per-unit organization writes on `religionorg.manage` (checked over the canonical graph). Writes are
audited in-process (D-Audit).
*/
type ReligionServiceClientWithAuth interface {
	ListTaxonRanks(ctx context.Context) (TaxonRankList, error)
	UpsertTaxonRank(ctx context.Context, requestArg UpsertTaxonRankRequest) (TaxonRank, error)
	ListClassifications(ctx context.Context) (ClassificationList, error)
	UpsertClassification(ctx context.Context, requestArg UpsertClassificationRequest) (Classification, error)
	ListOrgKinds(ctx context.Context) (OrgKindList, error)
	UpsertOrgKind(ctx context.Context, requestArg UpsertOrgKindRequest) (OrgKind, error)
	ListPolicyKinds(ctx context.Context) (PolicyKindList, error)
	UpsertPolicyKind(ctx context.Context, requestArg UpsertPolicyKindRequest) (PolicyKind, error)
	// Search/filter the taxonomy. Filters compose; results carry closure depth where a parent/root is given.
	ListTaxa(ctx context.Context, rankArg *string, parentArg *string, religionArg *string, queryArg *string, pageSizeArg *int, pageTokenArg *string) (TaxonPage, error)
	CreateTaxon(ctx context.Context, requestArg CreateTaxonRequest) (Taxon, error)
	GetTaxon(ctx context.Context, taxonIdArg string) (Taxon, error)
	UpdateTaxon(ctx context.Context, taxonIdArg string, requestArg UpdateTaxonRequest) (Taxon, error)
	DeleteTaxon(ctx context.Context, taxonIdArg string) error
	// Move a taxon under a new parent, recomputing the closure. Returns Religion:TaxonCycleDetected on a cycle.
	ReparentTaxon(ctx context.Context, taxonIdArg string, requestArg ReparentTaxonRequest) (Taxon, error)
	/*
	   Recompute the whole-tree taxonomy closure (admin maintenance). Pathed under /taxonomy (not
	   /taxa) so the static segment does not collide with the /taxa/{taxonId} wildcard route.
	*/
	RebuildClosure(ctx context.Context) (ClosureReport, error)
	// The taxon's resolved theism classifications (nearest declaring ancestor wins).
	GetEffectiveClassifications(ctx context.Context, taxonIdArg string) (ClassificationList, error)
	// Replace the theism tags declared directly on this taxon.
	SetTaxonClassifications(ctx context.Context, taxonIdArg string, requestArg SetClassificationsRequest) (ClassificationList, error)
	GetOrgProfile(ctx context.Context, unitIdArg string) (OrgProfile, error)
	SetOrgProfile(ctx context.Context, unitIdArg string, requestArg SetOrgProfileRequest) (OrgProfile, error)
	AddOrgClassification(ctx context.Context, unitIdArg string, requestArg AddOrgClassificationRequest) (OrgClassification, error)
	RemoveOrgClassification(ctx context.Context, unitIdArg string, linkIdArg string) error
	// Replace the unit's theism override set (empty list clears it, restoring inheritance).
	SetUnitTypeOverride(ctx context.Context, unitIdArg string, requestArg SetClassificationsRequest) (ClassificationList, error)
	GetEffectiveType(ctx context.Context, unitIdArg string) (EffectiveType, error)
	ListOrgPolicies(ctx context.Context, unitIdArg string) (OrgPolicyList, error)
	AddOrgPolicy(ctx context.Context, unitIdArg string, requestArg AddOrgPolicyRequest) (OrgPolicy, error)
	RemoveOrgPolicy(ctx context.Context, unitIdArg string, policyIdArg string) error
	/*
	   Create a child religious-body unit under this parent in the canonical graph. Rejected with
	   Religion:ChildCreationExcluded if the parent carries an active excludes_child_creation policy.
	*/
	CreateChildOrg(ctx context.Context, unitIdArg string, requestArg CreateChildOrgRequest) (OrgProfile, error)
	/*
	   Create a top-level religious body (M41 / D-UnifiedOrgGraph): a `church`-domain tenant
	   organization + its root religious-body unit + profile. Instance-level (religion.catalog.manage).
	*/
	CreateRootOrg(ctx context.Context, requestArg CreateRootOrgRequest) (OrgProfile, error)
	ListGradeCategories(ctx context.Context) (GradeCategoryList, error)
	UpsertGradeCategory(ctx context.Context, requestArg UpsertGradeCategoryRequest) (GradeCategory, error)
	// List clergy grades, optionally filtered to a tradition taxon (RID or code), ordered by tradition then ordinal.
	ListClergyGrades(ctx context.Context, traditionArg *string) (ClergyGradeList, error)
	UpsertClergyGrade(ctx context.Context, requestArg UpsertClergyGradeRequest) (ClergyGrade, error)
	ListOfficeTypes(ctx context.Context) (OfficeTypeList, error)
	UpsertOfficeType(ctx context.Context, requestArg UpsertOfficeTypeRequest) (OfficeType, error)
	ListPersonClergyCredentials(ctx context.Context, personIdArg string) (ClergyCredentialList, error)
	// The clergy roster of an organization unit (people holding a credential conferred by it).
	ListUnitClergyCredentials(ctx context.Context, unitIdArg string) (ClergyCredentialList, error)
	AddClergyCredential(ctx context.Context, personIdArg string, requestArg AddClergyCredentialRequest) (ClergyCredential, error)
	// Flip a credential's status (e.g. suspend/revoke) and/or set effective-dating. Never deletes.
	UpdateClergyCredential(ctx context.Context, credentialIdArg string, requestArg UpdateClergyCredentialRequest) (ClergyCredential, error)
	ListAffiliationTypes(ctx context.Context) (AffiliationTypeList, error)
	UpsertAffiliationType(ctx context.Context, requestArg UpsertAffiliationTypeRequest) (AffiliationType, error)
	// List a person's lay religious affiliations. pii:special — gated on affiliation.manage; the belief value is decrypted.
	ListPersonAffiliations(ctx context.Context, personIdArg string) (AffiliationList, error)
	AddAffiliation(ctx context.Context, personIdArg string, requestArg AddAffiliationRequest) (Affiliation, error)
	UpdateAffiliation(ctx context.Context, affiliationIdArg string, requestArg UpdateAffiliationRequest) (Affiliation, error)
	DeleteAffiliation(ctx context.Context, affiliationIdArg string) error
	ListSiteTypes(ctx context.Context) (SiteTypeList, error)
	UpsertSiteType(ctx context.Context, requestArg UpsertSiteTypeRequest) (SiteType, error)
	ListServiceTypes(ctx context.Context) (ServiceTypeList, error)
	UpsertServiceType(ctx context.Context, requestArg UpsertServiceTypeRequest) (ServiceType, error)
	// List an org unit's sites (exact coordinates, for authorized owners).
	ListUnitSites(ctx context.Context, unitIdArg string) (SiteList, error)
	CreateSite(ctx context.Context, unitIdArg string, requestArg CreateSiteRequest) (Site, error)
	UpdateSite(ctx context.Context, siteIdArg string, requestArg UpdateSiteRequest) (Site, error)
	DeleteSite(ctx context.Context, siteIdArg string) error
	ListSiteSchedules(ctx context.Context, siteIdArg string) (ServiceScheduleList, error)
	CreateSchedule(ctx context.Context, siteIdArg string, requestArg CreateScheduleRequest) (ServiceSchedule, error)
	DeleteSchedule(ctx context.Context, scheduleIdArg string) error
	ListUnitAliases(ctx context.Context, unitIdArg string) (AliasList, error)
	CreateAlias(ctx context.Context, unitIdArg string, requestArg CreateAliasRequest) (Alias, error)
	DeleteAlias(ctx context.Context, unitIdArg string, aliasIdArg string) error
	/*
	   Closure-aware PostGIS discovery search over PUBLIC sites. Supply a radius (lat+lng+radiusM via
	   ST_DWithin) or a bounding box (minLat/minLng/maxLat/maxLng via ST_Intersects); optionally filter
	   by a religion taxon (org units classified under it via the taxonomy closure), a service language/
	   weekday/online toggle, and a fuzzy match on the unit code/name or an alias. Coordinates are
	   coarsened per each site's publicPrecision.
	*/
	SearchSites(ctx context.Context, latArg *float64, lngArg *float64, radiusMArg *float64, minLatArg *float64, minLngArg *float64, maxLatArg *float64, maxLngArg *float64, religionArg *string, languageArg *string, dayOfWeekArg *int, onlineOnlyArg *bool, queryArg *string, pageSizeArg *int) (DiscoverySitePage, error)
}

